using Og.Core.Model;
using Og.Core.Runtime;

namespace Og.Core.Tests;

/// <summary>
/// Three changes that all come from the same complaint: people keep naming
/// things this world can see perfectly well and being told no.
///
/// Krasus typed "equip sword" holding a shortsword, with a cave troll in front
/// of him at ten hit points, and was told he was not carrying a sword. Tanril,
/// Kaleb and Krasus all tried to throw a bone and were all told "Nothing
/// happens". And nothing any place said could ever depend on what you had in
/// your hands or on whether the creature it was written about was still alive.
/// </summary>
public class GivingThingsTests
{
    private const string Rooms = """
    {
      "spawnLocation": 1,
      "items": [
        { "name": "bone", "description": "A gnawed bone." },
        { "name": "tin whistle", "description": "A cheap tin whistle." },
        { "name": "shortsword", "description": "A plain iron shortsword.", "kind": "weapon", "attackBonus": 1, "attackDice": 6 },
        { "name": "leather armor", "description": "Cracked leather.", "kind": "armor", "armorClassBonus": 2 }
      ],
      "monsters": [
        {
          "name": "cave troll",
          "description": "A cave troll blocks the passage.",
          "hitPoints": 20, "armorClass": 14, "attackStrength": 3, "attackDice": 8,
          "respawnSeconds": 900
        }
      ],
      "locations": [
        {
          "index": 1, "name": "Passage", "description": "A passage.",
          "connections": { "north": 2 },
          "monster": "cave troll",
          "interactions": [
            {
              "interactionId": "give",
              "if": [ "carrying:bone", "monster:cave troll" ],
              "triggers": [ "*bone*" ],
              "actions": [
                { "action": "describe", "parameters": [ "The troll goes down over the bone." ] },
                { "action": "removeitems", "parameters": [ "bone" ] }
              ]
            },
            {
              "interactionId": "no-troll",
              "if": [ "carrying:bone" ],
              "triggers": [ "*bone*" ],
              "actions": [
                { "action": "describe", "parameters": [ "There is nothing here to take it from you." ] }
              ]
            },
            {
              "interactionId": "no-bone",
              "triggers": [ "*bone*" ],
              "actions": [
                { "action": "describe", "parameters": [ "You have nothing to give it." ] }
              ]
            }
          ]
        },
        { "index": 2, "name": "Elsewhere", "description": "Somewhere else.", "connections": { "south": 1 } }
      ]
    }
    """;

    private static (GameEngine, Session, CollectingOutputSink) Ready()
    {
        var engine = new GameEngine(World.FromJson(Rooms), new CollectingEventSink(), seed: 5);
        var output = new CollectingOutputSink();
        var session = engine.Enter("Tester", output);
        output.Clear();
        return (engine, session, output);
    }

    private static void Give(GameEngine engine, Session session, string name) =>
        session.Character.Inventory.Add(engine.World.CreateItem(name)!);

    // ---- half a compound name is still the name of the thing -------------------

    [Fact]
    public void TheSwordKrasusWasNotCarrying()
    {
        var (engine, session, _) = Ready();
        Give(engine, session, "shortsword");

        engine.HandleInput(session, "equip sword");

        Assert.Equal("shortsword", session.Character.Weapon?.Name);
    }

    [Theory]
    [InlineData("sword", true)]
    [InlineData("short", true)]
    [InlineData("shortsword", true)]
    [InlineData("SWORD", true)]
    [InlineData("word", true)]
    [InlineData("or", false)]
    [InlineData("ord", false)]
    [InlineData("dagger", false)]
    public void PartOfAWordCountsOnceItIsLongEnoughToHaveBeenMeant(string spoken, bool expected)
    {
        var (engine, _, _) = Ready();
        Assert.Equal(expected, engine.World.CreateItem("shortsword")!.Matches(spoken));
    }

    /// <summary>
    /// The reason there is a floor under this at all: "one" is inside "bone" and
    /// "tin" is inside a great many words. Handing someone the wrong item because
    /// three letters happened to line up is worse than not understanding them.
    /// </summary>
    [Fact]
    public void ShortCoincidencesAreNotNames()
    {
        var (engine, _, _) = Ready();
        var bone = engine.World.CreateItem("bone")!;

        Assert.False(bone.Matches("one"));
        Assert.True(bone.Matches("bone"));
    }

    [Fact]
    public void TwoWordNamesStillAnswerToEitherWord()
    {
        var (engine, _, _) = Ready();
        var whistle = engine.World.CreateItem("tin whistle")!;

        Assert.True(whistle.Matches("whistle"));
        Assert.True(whistle.Matches("tin whistle"));
        Assert.True(whistle.Matches("tin"));
    }

    // ---- conditions that can see the world, not only their own flags -----------

    [Fact]
    public void AnInteractionCanRequireWhatYouAreHolding()
    {
        var (engine, session, output) = Ready();
        Give(engine, session, "bone");

        engine.HandleInput(session, "throw the bone to the troll");

        Assert.Contains("goes down over the bone", output.Text);
        Assert.Null(session.Character.FindItem("bone"));
    }

    [Fact]
    public void AndFallsThroughWhenYouAreNotHoldingIt()
    {
        var (engine, session, output) = Ready();

        engine.HandleInput(session, "throw the bone to the troll");

        Assert.Contains("You have nothing to give it", output.Text);
    }

    /// <summary>
    /// The one that matters most. Without a condition that can see the room, an
    /// interaction written for a living troll fires just as happily over its
    /// corpse — so anybody could walk in on a dead troll, throw it a bone, and
    /// collect whatever the scene was written to hand over.
    /// </summary>
    [Fact]
    public void AnInteractionCanRequireTheCreatureToStillBeAlive()
    {
        var (engine, session, output) = Ready();
        Give(engine, session, "bone");
        engine.World.FindLocation(1)!.Monster = null;

        engine.HandleInput(session, "throw the bone to the troll");

        Assert.Contains("nothing here to take it from you", output.Text);
        Assert.NotNull(session.Character.FindItem("bone"));
    }

    [Fact]
    public void ADeadCreatureIsNotAliveEitherEvenBeforeItIsClearedAway()
    {
        var (engine, session, output) = Ready();
        Give(engine, session, "bone");
        engine.World.FindLocation(1)!.Monster!.HitPoints = 0;

        engine.HandleInput(session, "throw the bone to the troll");

        Assert.Contains("nothing here to take it from you", output.Text);
    }

    [Fact]
    public void EquippedThingsCountAsCarriedForConditions()
    {
        var (engine, session, _) = Ready();
        session.Character.Weapon = engine.World.CreateItem("shortsword");

        Assert.True(engine.World.HasCondition(session, "carrying:sword"));
        Assert.False(engine.World.HasCondition(session, "carrying:bone"));
    }

    [Fact]
    public void PlainFlagsAreStillPlainFlags()
    {
        var (engine, session, _) = Ready();
        session.Character.Conditions.Add("seen-pattern");

        Assert.True(engine.World.HasCondition(session, "seen-pattern"));
        Assert.False(engine.World.HasCondition(session, "opened-cache"));
    }

    // ---- throwing ---------------------------------------------------------------

    /// <summary>
    /// The engine never decides what throwing achieves — it checks that the thing
    /// is in your hands and hands the sentence to the room. Where no room has an
    /// answer, the refusal has to be the honest one rather than "Nothing happens".
    /// </summary>
    [Fact]
    public void ThrowingSomewhereNothingCaresSaysSo()
    {
        var (engine, session, output) = Ready();
        Give(engine, session, "bone");
        engine.MoveTo(session, 2);
        output.Clear();

        engine.HandleInput(session, "throw the bone");

        Assert.Contains("nothing here would care where it landed", output.Text);
    }

    [Fact]
    public void ThrowingWhatYouHaveNotGotSaysThatInstead()
    {
        var (engine, session, output) = Ready();
        engine.MoveTo(session, 2);
        output.Clear();

        engine.HandleInput(session, "throw the bone");

        Assert.Contains("You aren't carrying a bone", output.Text);
    }

    /// <summary>
    /// "throw the bone at the troll" is a sentence about a bone. Without this the
    /// parser goes looking for an item called "bone at the troll".
    /// </summary>
    [Theory]
    [InlineData("throw the bone at the troll")]
    [InlineData("throw bone to troll")]
    [InlineData("give the bone to the troll")]
    [InlineData("toss bone towards the troll")]
    [InlineData("hurl the bone into the dark")]
    public void WhatIsBeingThrownIsReadOutOfTheWholeSentence(string spoken)
    {
        var (engine, session, output) = Ready();
        Give(engine, session, "bone");
        engine.MoveTo(session, 2);
        output.Clear();

        engine.HandleInput(session, spoken);

        Assert.Contains("nothing here would care where it landed", output.Text);
    }

    /// <summary>
    /// Nothing leaves your hands in the engine's half of this. The interaction
    /// that answers has to still be able to see the item, or "carrying:bone"
    /// would be false by the time the room got its turn.
    /// </summary>
    [Fact]
    public void ThrowingAloneNeverMovesAnything()
    {
        var (engine, session, _) = Ready();
        Give(engine, session, "bone");
        engine.MoveTo(session, 2);

        engine.HandleInput(session, "throw bone");

        Assert.NotNull(session.Character.FindItem("bone"));
        Assert.Empty(engine.World.FindLocation(2)!.Items);
    }
}

